mapper.select:
SELECT mbna.scheduling_id, mbna.wms_approve_record_id, mbna.order_number, mbna.job_id, war.review_status FROM mes_building_nesting_approve mbna LEFT JOIN wms_approve_record war ON war.data_id = mbna.wms_approve_record_id WHERE mbna.bool_delete_enum = 0 AND war.approve_process_type = 60004
AND war.review_status = #{reviewStatus}
AND mbna.job_id = #{jobId}
